const $=s=>document.querySelector(s),money=n=>n===null?'Sob consulta':(n/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
let products=[],editing=null,removing=null,settings=null,loading=false;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,options={}){const res=await fetch('/api/admin/'+path,{...options,headers:{'Content-Type':'application/json',...options.headers}});let data;try{data=await res.json();}catch{throw new Error('Sua sessão pode ter expirado. Atualize a página para entrar novamente.');}if(!res.ok)throw new Error(data.error||'Não foi possível concluir.');return data;}
function notify(message,error=false){const el=$('#message');el.textContent=message;el.classList.toggle('error',error);el.hidden=false;el.scrollIntoView({block:'nearest',behavior:'smooth'});}
function panelTheme(){const mode=$('#panel-theme').value;applyTheme({theme:mode,accent:'orange'});try{localStorage.setItem('up-admin-theme',mode);}catch{}}
try{$('#panel-theme').value=localStorage.getItem('up-admin-theme')||'light';}catch{}panelTheme();$('#panel-theme').addEventListener('change',panelTheme);matchMedia('(prefers-color-scheme: dark)').addEventListener('change',panelTheme);
document.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>{document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b===button));$('#view-products').hidden=button.dataset.view!=='products';$('#view-appearance').hidden=button.dataset.view!=='appearance';$('#message').hidden=true;if(button.dataset.view==='appearance')loadSettings();});
const status=p=>p.archived?['Removido','hidden']:p.stock===0?['Sem estoque','out']:p.stock<=p.low_stock?['Estoque baixo','low']:['Em estoque',''];
function render(){
 const active=products.filter(p=>!p.archived);$('#stat-all').textContent=active.length;$('#stat-in').textContent=active.filter(p=>p.stock>0).length;$('#stat-low').textContent=active.filter(p=>p.stock>0&&p.stock<=p.low_stock).length;$('#stat-out').textContent=active.filter(p=>p.stock===0).length;
 const low=active.filter(p=>p.stock>0&&p.stock<=p.low_stock);$('#stock-alert').hidden=!low.length;$('#stock-alert').textContent=`Reposição em vista: ${low.length} produto(s) com estoque baixo. Use o filtro para ver quais precisam de atenção.`;
 const filter=$('#stock-filter').value,query=$('#search').value.toLocaleLowerCase('pt-BR').trim(),category=$('#category-filter').value;
 const list=products.filter(p=>(filter==='archived'?p.archived:!p.archived)&&(!query||p.name.toLocaleLowerCase('pt-BR').includes(query))&&(!category||p.category===category)&&(filter==='in'?p.stock>0:filter==='out'?p.stock===0:filter==='low'?p.stock>0&&p.stock<=p.low_stock:filter==='hidden'?!p.published:true));
 $('#product-count').textContent='('+list.length+')';
 if(!list.length){$('#products-list').innerHTML=products.length?'<div class="empty"><h3>Nenhum produto por aqui</h3><p>Tente outro nome ou ajuste os filtros.</p></div>':'<div class="empty"><h3>Sua vitrine começa aqui.</h3><p>Cadastre seu primeiro produto com preço, foto e quantidade.</p><button class="primary" id="first-product">+ Adicionar primeiro produto</button></div>';$('#first-product')?.addEventListener('click',()=>openProduct());return;}
 $('#products-list').innerHTML='<div class="table-scroll"><table><thead><tr><th>Produto</th><th>Preço</th><th>Estoque</th><th>Vitrine</th><th>Ações</th></tr></thead><tbody>'+list.map(p=>{const [label,klass]=status(p);return `<tr><td><div class="product-cell">${p.image?`<img src="${esc(p.image)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:'<span class="photo-placeholder" aria-hidden="true">▦</span>'}<div><strong>${esc(p.name)}</strong><small>${esc(p.category)} · ${esc(p.condition)}${p.featured?' · Destaque':''}</small></div></div></td><td>${money(p.price)}</td><td><strong>${p.stock}</strong> un.<br><span class="badge ${klass}">${label}</span></td><td><span class="badge ${p.published&&!p.archived?'':'hidden'}">${p.archived?'Removido':p.published?'Visível':'Oculto'}</span></td><td><div class="row-actions">${p.archived?`<button data-action="restore" data-id="${esc(p.id)}">Restaurar</button>`:`<button data-action="edit" data-id="${esc(p.id)}">Editar</button><button class="remove" data-action="remove" data-id="${esc(p.id)}">Remover</button>`}</div></td></tr>`;}).join('')+'</tbody></table></div>';
 $('#products-list').querySelectorAll('img').forEach(img=>img.onerror=()=>{const span=document.createElement('span');span.className='photo-placeholder';span.textContent='▦';img.replaceWith(span);});
}
async function load(){if(loading)return;loading=true;$('#refresh').disabled=true;try{products=(await api('products')).products;render();$('#add-product').disabled=false;}catch(e){notify(e.message,true);if(!products.length)$('#products-list').innerHTML='<div class="empty"><h3>Não foi possível carregar</h3><p>Use “Atualizar” para tentar novamente.</p></div>';}finally{loading=false;$('#refresh').disabled=false;}}
$('#refresh').onclick=load;$('#search').oninput=render;$('#category-filter').onchange=render;$('#stock-filter').onchange=render;document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{$('#stock-filter').value=b.dataset.filter;render();});
function openProduct(p=null){editing=p;const f=$('#product-form');f.reset();$('#dialog-title').textContent=p?'Editar produto':'Adicionar produto';$('#form-error').textContent='';if(p){for(const key of ['name','category','condition','description','stock','low_stock','image'])f.elements[key].value=p[key];f.elements.price.value=p.price===null?'':(p.price/100).toFixed(2);f.elements.published.checked=Boolean(p.published);f.elements.featured.checked=Boolean(p.featured);}$('#product-dialog').showModal();f.elements.name.focus();}
$('#add-product').onclick=()=>openProduct();document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.close).close());
$('#products-list').onclick=async e=>{const b=e.target.closest('[data-action]');if(!b)return;const p=products.find(x=>x.id===b.dataset.id);if(!p)return;if(b.dataset.action==='edit')openProduct(p);if(b.dataset.action==='remove'){removing=p;$('#remove-name').textContent=p.name;$('#remove-error').textContent='';$('#remove-dialog').showModal();}if(b.dataset.action==='restore'){b.disabled=true;try{await api('products/'+p.id,{method:'PATCH',body:JSON.stringify({archived:false,version:p.version})});notify('Produto restaurado.');await load();}catch(err){notify(err.message,true);b.disabled=false;}}};
$('#product-form').onsubmit=async e=>{e.preventDefault();const f=e.target,button=$('#save-product');const b=Object.fromEntries(new FormData(f));b.price=b.price===''?null:Math.round(Number(b.price)*100);b.stock=Number(b.stock);b.low_stock=Number(b.low_stock);b.featured=f.elements.featured.checked;b.published=f.elements.published.checked;if(editing)b.version=editing.version;button.disabled=true;button.textContent='Salvando…';$('#form-error').textContent='';try{await api('products'+(editing?'/'+editing.id:''),{method:editing?'PUT':'POST',body:JSON.stringify(b)});$('#product-dialog').close();notify('Produto salvo. A vitrine já foi atualizada.');await load();}catch(err){$('#form-error').textContent=err.message;}finally{button.disabled=false;button.textContent='Salvar produto';}};
$('#remove-form').onsubmit=async e=>{e.preventDefault();if(!removing)return;const button=$('#confirm-remove');button.disabled=true;try{await api('products/'+removing.id,{method:'PATCH',body:JSON.stringify({archived:true,version:removing.version})});$('#remove-dialog').close();notify('Produto removido. Você pode restaurá-lo pelo filtro “Removidos”.');await load();}catch(err){$('#remove-error').textContent=err.message;}finally{button.disabled=false;}};
async function loadSettings(){try{settings=await api('settings');const f=$('#appearance-form');f.elements.theme.value=settings.theme;f.elements.accent.value=settings.accent;$('#save-theme').disabled=false;$('#theme-error').textContent='';}catch(e){$('#theme-error').textContent=e.message;}}
$('#appearance-form').onsubmit=async e=>{e.preventDefault();if(!settings)return;const button=$('#save-theme');button.disabled=true;const f=e.target;try{settings=await api('settings',{method:'PUT',body:JSON.stringify({theme:f.elements.theme.value,accent:f.elements.accent.value,version:settings.version})});notify('Aparência salva! Abra ou atualize a vitrine para conferir.');}catch(err){$('#theme-error').textContent=err.message;}finally{button.disabled=false;}};
load();
